import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"29、【坎】 坎下坎上","description":"横渠易说 - 29、【坎】 坎下坎上","frontmatter":{"title":"29、【坎】 坎下坎上","description":"横渠易说 - 29、【坎】 坎下坎上"},"headers":[],"relativePath":"zh/classics/hengqu/031.md","filePath":"zh/classics/hengqu/031.md"}'),l={name:"zh/classics/hengqu/031.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_29、【坎】-坎下坎上" tabindex="-1">29、【坎】 坎下坎上 <a class="header-anchor" href="#_29、【坎】-坎下坎上" aria-label="Permalink to “29、【坎】 坎下坎上”">​</a></h1><p>习坎，重袭之义。八纯卦惟此加“习”者，余皆一字可尽其义，坎取其险，故重之而其险乃着也。 色以离见，声以震闻，臭以巽知，味以坎达。 坎离者，天地之中二气之正交。然离本阴卦，坎本阳卦，以此见二气其本如此而交性也，非此二物则无易。</p><h3 id="彖曰-习坎-重险也-水流而不盈-行险而不失其信。-维心亨-乃以刚中也。-行有尚-往有功也。天险-不可升也-地险-山川丘陵也。王公设险以守其国-险之时用大矣哉" tabindex="-1">彖曰：习坎，重险也，水流而不盈，行险而不失其信。“维心亨”，乃以刚中也。“行有尚”，往有功也。天险，不可升也；地险，山川丘陵也。王公设险以守其国，险之时用大矣哉! <a class="header-anchor" href="#彖曰-习坎-重险也-水流而不盈-行险而不失其信。-维心亨-乃以刚中也。-行有尚-往有功也。天险-不可升也-地险-山川丘陵也。王公设险以守其国-险之时用大矣哉" aria-label="Permalink to “彖曰：习坎，重险也，水流而不盈，行险而不失其信。“维心亨”，乃以刚中也。“行有尚”，往有功也。天险，不可升也；地险，山川丘陵也。王公设险以守其国，险之时用大矣哉!”">​</a></h3><h3 id="象曰-水洊至-习坎-君子以常德行-习教事。" tabindex="-1">象曰：水洊至，习坎，君子以常德行，习教事。 <a class="header-anchor" href="#象曰-水洊至-习坎-君子以常德行-习教事。" aria-label="Permalink to “象曰：水洊至，习坎，君子以常德行，习教事。”">​</a></h3><p>可盈则非谓重险也，中柔则心无常，何能亨也!内外皆险，义不可止，故行有尚也。 坎维心亨故行有尚，外虽积险，苟处之心亨不疑，则虽难必济而往有功也。今水临万仞之山，要下即下，无复凝滞(人)［之］在前，惟知有义理而已，则复何回避，所以心通。</p><h3 id="初六-习坎-入于坎窞-凶。-象曰-习坎入坎-失道凶也。" tabindex="-1">初六，习坎，入于坎窞，凶。 象曰：习坎入坎，失道凶也。 <a class="header-anchor" href="#初六-习坎-入于坎窞-凶。-象曰-习坎入坎-失道凶也。" aria-label="Permalink to “初六，习坎，入于坎窞，凶。 象曰：习坎入坎，失道凶也。”">​</a></h3><p>比于二无出险之志，故云“入于坎窞”也。</p><h3 id="九二-坎有险-求小得。-象曰-求小得-未出中也。" tabindex="-1">九二，坎有险，求小得。 象曰：“求小得”，未出中也。 <a class="header-anchor" href="#九二-坎有险-求小得。-象曰-求小得-未出中也。" aria-label="Permalink to “九二，坎有险，求小得。 象曰：“求小得”，未出中也。”">​</a></h3><p>险难之际，弱必附强，上下俱阴，求必见从，故求则必小得，然二居险中而未出也。</p><h3 id="六三-来之坎坎-险且枕-入于坎窞勿用。-象曰-来之坎坎-终无功也。" tabindex="-1">六三，来之坎坎，险且枕，入于坎窞勿用。 象曰：“来之坎坎”，终无功也。 <a class="header-anchor" href="#六三-来之坎坎-险且枕-入于坎窞勿用。-象曰-来之坎坎-终无功也。" aria-label="Permalink to “六三，来之坎坎，险且枕，入于坎窞勿用。 象曰：“来之坎坎”，终无功也。”">​</a></h3><p>前之入险退(来)［求］，枕险入窞，与初六同。</p><h3 id="六四-樽酒簋贰用缶。纳约自牖-终无咎。-象曰-樽酒簋贰-刚柔际也。" tabindex="-1">六四，樽酒簋贰用缶。纳约自牖，终无咎。 象曰：“樽酒簋贰”，刚柔际也。 <a class="header-anchor" href="#六四-樽酒簋贰用缶。纳约自牖-终无咎。-象曰-樽酒簋贰-刚柔际也。" aria-label="Permalink to “六四，樽酒簋贰用缶。纳约自牖，终无咎。 象曰：“樽酒簋贰”，刚柔际也。”">​</a></h3><p>四五俱得阴阳之正，险阻之际，近而相得，诚素既接，虽简略于礼无咎也。上比于五，有进出之渐，故无凶。</p><h3 id="九五-坎不盈-祗既平-无咎。-象曰-坎不盈-中未大也。" tabindex="-1">九五，坎不盈，祗既平，无咎。 象曰：“坎不盈”，中未大也。 <a class="header-anchor" href="#九五-坎不盈-祗既平-无咎。-象曰-坎不盈-中未大也。" aria-label="Permalink to “九五，坎不盈，祗既平，无咎。 象曰：“坎不盈”，中未大也。”">​</a></h3><p>险难垂出而下比于四，不能勉成其功，光大其志，故圣人惜之曰“祗既平无咎”而已矣，不能往有功也。一本云：坎盈则进而往有尚矣。</p><h3 id="上六-系用徽纆-置于丛棘-三岁不得-凶。-象曰-上六失道-凶三岁也。" tabindex="-1">上六，系用徽纆，置于丛棘，三岁不得，凶。 象曰：上六失道，凶三岁也。 <a class="header-anchor" href="#上六-系用徽纆-置于丛棘-三岁不得-凶。-象曰-上六失道-凶三岁也。" aria-label="Permalink to “上六，系用徽纆，置于丛棘，三岁不得，凶。 象曰：上六失道，凶三岁也。”">​</a></h3><p>上六过中，逃险而失道者也，不附比阳中，几于迷复之凶，故为所系累也。阴柔不能附比于阳，处险之极乘刚，宜其为所拘戮也。</p>',17)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
